// 각 설비 reader 가 보낸 부분 dict 를 flow context 에 누적.
// parser 는 msg.payload = {equipment_id, tags} 형태로 전달한다.
const p = msg.payload || {};
const eq = p.equipment_id;
if (!eq) return null;
const buf = flow.get('equipments') || {};
const prev = buf[eq] || { data: {} };
prev.data = Object.assign(prev.data || {}, p.tags || {});
prev.last_update_ms = Date.now();
buf[eq] = prev;
flow.set('equipments', buf);
return null;

// payload 를 OPC UA Server 변수로 발행
//
// node-red-contrib-opcua 의 OpcUa-Server 는 2단계 프로토콜:
//   1) addVariable 명령으로 주소공간에 노드 등록
//      msg.topic   = 'ns=2;s=<name>;datatype=<DT>'
//      msg.payload = { opcuaCommand: 'addVariable' }
//   2) 이후 Variable 명령으로 값 갱신
//      msg.payload = { messageType:'Variable', namespace:2,
//                      variableName:<name>, variableValue:<val>, datatype:<DT> }
//
// addVariable 과 Variable 을 같은 tick 의 연속된 msg 로 보내면
// OpcUa-Server 가 주소공간 등록을 끝내기 전에 Variable 갱신이 들어와서
// "Variable not found" 에러가 다수 발생한다.
//
// 근본 해결책 (race 완전 제거):
//   1) 변수별 상태를 3단계로 관리: 'new' -> 'pending' -> 'ready'
//      - 처음 만난 변수는 addVariable 만 보내고 'pending' 으로 표시
//      - 다음 tick 부터 'pending' 인 변수는 Variable update SKIP 하고 'ready' 로 승격
//      - 'ready' 부터 실제 Variable update 전송
//   2) 즉 addVariable 보낸 tick (1초 간격) + 2 tick 뒤부터 update 시작
//      → OpcUa-Server 가 등록을 끝낼 약 1초 이상 확보
//   3) Variable update 는 contrib-opcua array payload 형식으로 한번에 묶어 전송
const EXPECTED_TYPES = {"CAST-01": {"power": "bool", "injection_pressure_sp": "float", "mold_temperature_sp": "float", "cooling_flow_sp": "float", "injection_pressure": "float", "mold_temperature": "float", "cooling_flow": "float", "progress": "float"}, "CNC-01": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-02": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-03": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "WASH-01": {"power": "bool", "cleaning_concentration_sp": "float", "cleaning_temperature_sp": "float", "cleaning_pressure_sp": "float", "cleaning_concentration": "float", "cleaning_temperature": "float", "cleaning_pressure": "float", "progress": "float"}, "ASSY-01": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "ASSY-02": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "TEST-01": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}, "TEST-02": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}};
const p = msg.payload;
if (!p) return null;
const lineId = p.line_id;
// state['name'] = 'pending' | 'ready'
const state = flow.get('opcua_state') || {};
const addMsgs = [];
const varList = [];

function coerce(value, dtype) {
  if (value === null || value === undefined) {
    if (dtype === 'Boolean') return false;
    if (dtype === 'Int32') return 0;
    if (dtype === 'Double' || dtype === 'Float') return 0.0;
    return '';
  }
  return value;
}

function publish(name, value, dtype) {
  const v = coerce(value, dtype);
  const s = state[name];
  if (!s) {
    // 첫 발견: addVariable 만 보냄
    addMsgs.push({
      topic: `ns=2;s=${name};datatype=${dtype}`,
      payload: { opcuaCommand: 'addVariable' },
    });
    state[name] = 'pending';
    return;
  }
  if (s === 'pending') {
    // 한 tick 더 기다림 -> ready 로 승격, 이번 tick 도 update skip
    state[name] = 'ready';
    return;
  }
  // ready: 실제 update
  varList.push({
    messageType: 'Variable',
    namespace: 2,
    variableName: name,
    variableValue: v,
    datatype: dtype,
  });
}

publish(`${lineId}.payload`,         JSON.stringify(p),     'String');
publish(`${lineId}.line_ts`,         p.ts,                   'String');
publish(`${lineId}.schema_version`,  p.schema_version,       'String');
for (const [eq, slot] of Object.entries(p.equipments || {})) {
  publish(`${lineId}.${eq}.status`,  slot.status,            'String');
  publish(`${lineId}.${eq}.ts`,      slot.ts,                'String');
  publish(`${lineId}.${eq}.quality`, slot.quality,           'String');
  const typeMap = (EXPECTED_TYPES[eq] || {});
  for (const [tag, val] of Object.entries(slot.data || {})) {
    let dtype;
    const declared = typeMap[tag];
    if (declared === 'bool') dtype = 'Boolean';
    else if (declared === 'int') dtype = 'Int32';
    else if (declared === 'float') dtype = 'Double';
    else {
      // 알려지지 않은 동적 tag (cycle_time, progress 등) — 무조건 Double 로 등록.
      if (typeof val === 'boolean') dtype = 'Boolean';
      else if (typeof val === 'number') dtype = 'Double';
      else dtype = 'String';
    }
    publish(`${lineId}.${eq}.data.${tag}`, val, dtype);
  }
}
flow.set('opcua_state', state);

// 단계 1: addVariable msg 들 즉시 전송 (array-of-messages 출력 형식)
if (addMsgs.length > 0) {
  node.send([addMsgs]);
}

// 단계 2: Variable update 는 array payload 로 한번에 전송 (state='ready' 인 것만)
//   addMsgs 가 있는 tick (새 변수 발견된 tick) 은 800ms 지연으로 안전 마진,
//   안정 상태에선 50ms 정도 지연으로 send 순서만 보장.
if (varList.length > 0) {
  const delay = (addMsgs.length > 0) ? 800 : 50;
  setTimeout(() => {
    node.send({ payload: varList });
  }, delay);
}

return null;

// 1초마다 라인 페이로드 발행 + cycle_time 산출
const LINE_ID = "LINE-02";
const SCHEMA_VERSION = "1.0";
const EQUIPMENTS = ["CAST-01", "CNC-01", "CNC-02", "CNC-03", "WASH-01", "ASSY-01", "ASSY-02", "TEST-01", "TEST-02"];
// 설비별 기대 tag 맵: { eq_id: { tag_name: data_type } }
// 아직 읽히지 않은 값은 data_type 기본값으로 채워 서
// 통합 DAS 가 OPC UA 변수 누락 에러를 내지 않도록 보장.
const EXPECTED_TAGS = {"CAST-01": {"power": "bool", "injection_pressure_sp": "float", "mold_temperature_sp": "float", "cooling_flow_sp": "float", "injection_pressure": "float", "mold_temperature": "float", "cooling_flow": "float", "progress": "float"}, "CNC-01": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-02": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "CNC-03": {"power": "bool", "spindle_speed_sp": "int", "tool_usage_sp": "float", "coolant_flow_sp": "float", "spindle_speed": "int", "tool_usage": "float", "coolant_flow": "float", "progress": "float"}, "WASH-01": {"power": "bool", "cleaning_concentration_sp": "float", "cleaning_temperature_sp": "float", "cleaning_pressure_sp": "float", "cleaning_concentration": "float", "cleaning_temperature": "float", "cleaning_pressure": "float", "progress": "float"}, "ASSY-01": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "ASSY-02": {"power": "bool", "tightening_torque_sp": "float", "tightening_angle_sp": "float", "press_force_sp": "float", "tightening_torque": "float", "tightening_angle": "float", "press_force": "float", "progress": "float"}, "TEST-01": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}, "TEST-02": {"power": "bool", "bore_dimension_sp": "float", "hole_dimension_sp": "float", "bore_dimension": "float", "hole_dimension": "float", "result_ok": "bool", "progress": "float"}};
// 설비별 nominal cycle_sec (첫 사이클 완료 전 cycle_time 기본값 및 표시용)
const NOMINAL_CYCLE = {"CAST-01": 60, "CNC-01": 180, "CNC-02": 180, "CNC-03": 180, "WASH-01": 60, "ASSY-01": 120, "ASSY-02": 120, "TEST-01": 120, "TEST-02": 120};
function defaultForType(t) {
  if (t === 'bool') return false;
  if (t === 'int') return 0;
  if (t === 'float') return 0.0;
  return '';
}
const STALE_MS = 3000;  // 3초 이상 미갱신 -> UNCERTAIN

const buf = flow.get('equipments') || {};
const cyc = flow.get('cycle_state') || {};  // { eq: { acc, last_cycle_time } }
const now = Date.now();
const nowIso = new Date(now).toISOString();

function classify(data, last_update_ms) {
  if (!data || Object.keys(data).length === 0) {
    return { status: 'OFF', quality: 'BAD' };
  }
  // status (시모에서는 OFF / RUN 두 개만 생성. WARNING/DANGER 는 향후 확장)
  const status = data.power === false ? 'OFF' : 'RUN';
  // quality
  let quality;
  if (!last_update_ms) quality = 'BAD';
  else if (now - last_update_ms > STALE_MS) quality = 'UNCERTAIN';
  else quality = 'GOOD';
  return { status, quality };
}

const equipments = {};
for (const eq_id of EQUIPMENTS) {
  const slot = buf[eq_id] || {};
  const data = Object.assign({}, slot.data || {});
  // 기대 tag 중 아직 안 온 것은 data_type 기본값으로 미리 박아서
  // PUBLISH 가 제대로 된 dtype 으로 addVariable 하게 함.
  const expected = EXPECTED_TAGS[eq_id] || {};
  for (const [tagName, tagType] of Object.entries(expected)) {
    if (!(tagName in data)) data[tagName] = defaultForType(tagType);
  }
  const { status, quality } = classify(data, slot.last_update_ms);

  // ----- cycle_time 산출 -----
  // 한 사이클(progress 누적이 1.0 도달) 이 끝난 시점의 경과시간을 측정해
  // "마지막으로 완료된 사이클의 cycle_time" 으로 저장하고,
  // 다음 사이클이 끝날 때까지 매 tick 같은 값을 반환 (hold).
  // 첫 사이클이 끝나기 전까지는 설비 명세의 cycle_sec(60/180/120)을 기본값으로.
  const NOMINAL = (NOMINAL_CYCLE[eq_id] || 60);
  let st = cyc[eq_id] || {
    acc: 0.0,
    last_cycle_time: NOMINAL,   // 부팅 직후 기본값
    start_ms: now,
  };
  if (status === 'RUN' && typeof data.progress === 'number') {
    st.acc += data.progress;
    if (st.acc >= 1.0) {
      const dt = (now - (st.start_ms || now)) / 1000.0;
      st.last_cycle_time = +dt.toFixed(2);   // 다음 100% 도달 전까지 hold
      st.acc = 0.0;
      st.start_ms = now;
    }
  }
  // OFF 일 때는 acc / start_ms 유지 (다음 RUN 에서 이어 계산).
  cyc[eq_id] = st;
  data.cycle_time = st.last_cycle_time;  // 항상 hold 된 값을 전달

  equipments[eq_id] = {
    status: status,
    ts: slot.last_update_ms ? new Date(slot.last_update_ms).toISOString() : nowIso,
    quality: quality,
    data: data,
  };
}

flow.set('cycle_state', cyc);

const payload = {
  ts: nowIso,
  line_id: LINE_ID,
  schema_version: SCHEMA_VERSION,
  equipments: equipments,
};

return { payload: payload };

// MC Read 결과 -> 평탄 dict
// addressType=str, outputFormat=0(JSON object)인 경우 msg.payload 는
// 단일값(스칼라/bool) 또는 객체일 수 있다. mcprotocol contrib 동작:
//   - 단일 디바이스(M0, D0)   : 스칼라 또는 길이1 배열
//   - DFLOAT0,N (N>=2)        : 배열
//   - 단일 DFLOAT0            : 스칼라 float
const NAMES = ["power"];       // 이 read 가 커버하는 tag name 순서
const TYPE  = "bit";           // 'bit' | 'int' | 'float'
const p = msg.payload;
const arr = Array.isArray(p) ? p : [p];
const tags = {};
if (TYPE === 'bit') {
  NAMES.forEach((n, i) => { tags[n] = !!arr[i]; });
} else if (TYPE === 'int') {
  NAMES.forEach((n, i) => { tags[n] = (arr[i] | 0); });
} else if (TYPE === 'float') {
  NAMES.forEach((n, i) => { tags[n] = +Number(arr[i]).toFixed(3); });
}
msg.payload = { equipment_id: "CAST-01", tags: tags };
return msg;

