// float -> uint16[2] BE 변환
// 시뮬 modbus_server 가 readFloatBE(reg0_hi << 16 | reg1_lo) 로 해석하므로
// register 순서는 [hi_word, lo_word] (big-endian word order)
// modbus-write 노드가 dataType=MHoldingRegisters 면 FC=16, payload 가 array 면
// 그대로 values 로 쓴다 (contrib-modbus modbus-write.js#105).
const v = Number(msg.payload);
if (!Number.isFinite(v)) {
  node.warn('invalid payload for float write: ' + msg.payload);
  return null;
}
const buf = Buffer.alloc(4);
buf.writeFloatBE(v, 0);
const hi = buf.readUInt16BE(0);
const lo = buf.readUInt16BE(2);
msg.payload = [hi, lo];
return msg;

